console.log("Loadhtml.js: Function running");const targetEl=document.querySelector(".target"),loadSnippet=t=>{fetch(`html${t}.html`).then((t=>{if(t.ok)return t.text()})).then((t=>{targetEl.innerHTML=t}))};window.onload=function(){setTimeout(document.querySelector(".eventsbutton").addEventListener("click",loadSnippet(1)),5e3),setTimeout(document.querySelector(".blogbutton").addEventListener("click",loadSnippet(2)),5e3),console.log("Loadhtml.js: Buttons loaded")};